// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Try calling sudicideAnyone() from an arbitrary caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        // The rule: if caller is owner, call succeeds; otherwise reverts
        // We cannot directly read owner (private), so we deduce:
        // After successful selfdestruct, the contract has no code, so a second call would fail.
        // But to avoid reading private state, we check the result of this call and then check code size.
        if (success) {
            // If call succeeded, then contract should have no code (selfdestruct occurred)
            uint256 codeSize;
            assembly { codeSize := extcodesize(sload(c.slot)) } // This would fail; instead use address(c)
            // Actually, we can use getCode helper but simpler: check that a subsequent call reverts
            (bool call2, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
            assertTrue(!call2, "After selfdestruct, further calls should fail");
        } else {
            // If call reverted, caller was not owner and contract should still be alive
            // Check that the contract still has code (i.e., not destroyed)
            uint256 codeSize;
            assembly { codeSize := extcodesize(address()) }
            assertTrue(codeSize > 0, "Non-owner revert should not destroy contract");
        }
    }
}
